/**
 * Google Fonts catalog for the SPA: lazy-loaded, searched, and previewed.
 *
 * The catalog JSON (slug / family / category triples, generated by
 * scripts/gen-google-fonts.py) is code-split into its own chunk; the font
 * *binaries* load lazily in two places:
 * - live preview → a <link> to the Google Fonts stylesheet (the browser
 *   fetches the webfont so the preview shows the real family), and
 * - the served badge → the API downloads the TTF and caches it.
 */

export interface GoogleFontInfo {
  slug: string;
  family: string;
  category: string;
}

type RawEntry = [slug: string, family: string, category: string];

let cache: GoogleFontInfo[] | null = null;

/** Loads (once) and returns the full Google Fonts catalog, sorted by slug. */
export async function loadGoogleFonts(): Promise<GoogleFontInfo[]> {
  if (!cache) {
    const { default: entries } = await import("./google-fonts-catalog.json");
    cache = (entries as RawEntry[]).map(([slug, family, category]) => ({
      slug,
      family,
      category,
    }));
  }
  return cache;
}

/** Synchronous access once the catalog has loaded (null before). */
export function googleFontsSync(): GoogleFontInfo[] | null {
  return cache;
}

/** A resolved font picker selection. */
export type FontChoice = { slug: string; family: string; bundled: boolean } | "source";

/**
 * Looks a font up across the bundled families and the Google catalog, by
 * slug or exact family name. `null` = not a font the server can render.
 */
export function resolveFontChoice(
  value: string,
  catalog: GoogleFontInfo[] | null,
  bundled: ReadonlyArray<{ slug: string; family: string }>,
): FontChoice | null {
  const v = value.trim();
  if (!v || v === "source") return "source";
  const hit = bundled.find((f) => f.slug === v || f.family.replace(/'/g, "") === v);
  if (hit) return { slug: hit.slug, family: hit.family.replace(/'/g, ""), bundled: true };
  if (!catalog) return null;
  const google = catalog.find((f) => f.slug === v || f.family === v);
  if (google) return { slug: google.slug, family: google.family, bundled: false };
  return null;
}

/** Case-insensitive prefix-first search over the catalog. */
export function searchGoogleFonts(
  query: string,
  catalog: GoogleFontInfo[],
  limit = 12,
): GoogleFontInfo[] {
  const q = query.trim().toLowerCase();
  if (!q) return catalog.slice(0, limit);
  const prefix: GoogleFontInfo[] = [];
  const substring: GoogleFontInfo[] = [];
  for (const f of catalog) {
    const fam = f.family.toLowerCase();
    const slug = f.slug.toLowerCase();
    if (fam.startsWith(q) || slug.startsWith(q)) prefix.push(f);
    else if (fam.includes(q) || slug.includes(q)) substring.push(f);
    if (prefix.length >= limit) break;
  }
  return [...prefix, ...substring].slice(0, limit);
}

/**
 * Injects (once per family) the Google Fonts stylesheet link so the browser
 * can render the family in the live preview.
 */
export function ensureGoogleFontLoaded(family: string): void {
  if (typeof document === "undefined") return;
  const key = family.replace(/['"]/g, "");
  const id = `vx-google-font-${key.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}`;
  if (document.getElementById(id)) return;
  const link = document.createElement("link");
  link.id = id;
  link.rel = "stylesheet";
  link.dataset.vxFont = key;
  link.href = `https://fonts.googleapis.com/css2?family=${encodeURIComponent(key).replace(/%20/g, "+")}&display=swap`;
  document.head.appendChild(link);
}
